'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import Link from 'next/link'
import { Search, ChevronRight, Users, Calendar } from 'lucide-react'

interface BookingRow {
  customer_name: string
    customer_email: string
      customer_phone: string | null
        status: string
          created_at: string
          }

          interface Customer {
            name: string
              email: string
                phone: string | null
                  totalRequests: number
                    bookedCount: number
                      latestDate: string
                        firstDate: string
                        }

                        function getInitials(name: string): string {
                          const parts = name.trim().split(' ')
                            if (parts.length === 1) return parts[0].charAt(0).toUpperCase()
                              return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
                              }

                              function getAvatarColor(email: string): string {
                                const colors = [
                                    'bg-yellow-400/20 text-yellow-400',
                                        'bg-blue-500/20 text-blue-400',
                                            'bg-green-500/20 text-green-400',
                                                'bg-purple-500/20 text-purple-400',
                                                    'bg-orange-500/20 text-orange-400',
                                                        'bg-pink-500/20 text-pink-400',
                                                            'bg-teal-500/20 text-teal-400',
                                                                'bg-red-500/20 text-red-400',
                                                                  ]
                                                                    let hash = 0
                                                                      for (let i = 0; i < email.length; i++) hash = (hash * 31 + email.charCodeAt(i)) & 0xffffffff
                                                                        return colors[Math.abs(hash) % colors.length]
                                                                        }

                                                                        function formatDate(iso: string): string {
                                                                          return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
                                                                          }

                                                                          function SkeletonRow() {
                                                                            return (
                                                                                <div className="bg-[#0B0F17] border border-white/6 rounded-xl p-4 flex items-center gap-4 animate-pulse">
                                                                                      <div className="w-10 h-10 rounded-full bg-white/8 flex-shrink-0" />
                                                                                            <div className="flex-1 min-w-0">
                                                                                                    <div className="h-4 w-32 bg-white/8 rounded mb-2" />
                                                                                                            <div className="h-3 w-48 bg-white/5 rounded" />
                                                                                                                  </div>
                                                                                                                        <div className="h-3 w-16 bg-white/5 rounded" />
                                                                                                                            </div>
                                                                                                                              )
                                                                                                                              }
                                                                                                                              
                                                                                                                              export default function CustomersPage() {
                                                                                                                                const [rows, setRows] = useState<BookingRow[]>([])
                                                                                                                                  const [loading, setLoading] = useState(true)
                                                                                                                                    const [error, setError] = useState<string | null>(null)
                                                                                                                                      const [search, setSearch] = useState('')
                                                                                                                                      
                                                                                                                                        async function fetchData() {
                                                                                                                                            setLoading(true)
                                                                                                                                                setError(null)
                                                                                                                                                    try {
                                                                                                                                                          const supabase = createClient()
                                                                                                                                                                const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                                      if (!user) { setError('Not signed in'); setLoading(false); return }
                                                                                                                                                                            const { data, error: dbErr } = await supabase
                                                                                                                                                                                    .from('booking_requests')
                                                                                                                                                                                            .select('customer_name, customer_email, customer_phone, status, created_at')
                                                                                                                                                                                                    .eq('pro_id', user.id)
                                                                                                                                                                                                            .order('created_at', { ascending: false })
                                                                                                                                                                                                                  if (dbErr) { setError(dbErr.message); setLoading(false); return }
                                                                                                                                                                                                                        setRows(data || [])
                                                                                                                                                                                                                            } catch (e: unknown) {
                                                                                                                                                                                                                                  setError(e instanceof Error ? e.message : 'Failed to load')
                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                          setLoading(false)
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                              useEffect(() => { fetchData() }, [])
                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                const customerMap = new Map<string, Customer>()
                                                                                                                                                                                                                                                  for (const row of rows) {
                                                                                                                                                                                                                                                      const email = row.customer_email
                                                                                                                                                                                                                                                          if (!customerMap.has(email)) {
                                                                                                                                                                                                                                                                customerMap.set(email, {
                                                                                                                                                                                                                                                                        name: row.customer_name,
                                                                                                                                                                                                                                                                                email,
                                                                                                                                                                                                                                                                                        phone: row.customer_phone,
                                                                                                                                                                                                                                                                                                totalRequests: 0,
                                                                                                                                                                                                                                                                                                        bookedCount: 0,
                                                                                                                                                                                                                                                                                                                latestDate: row.created_at,
                                                                                                                                                                                                                                                                                                                        firstDate: row.created_at,
                                                                                                                                                                                                                                                                                                                              })
                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                      const c = customerMap.get(email)!
                                                                                                                                                                                                                                                                                                                                          c.totalRequests += 1
                                                                                                                                                                                                                                                                                                                                              if (row.status === 'booked') c.bookedCount += 1
                                                                                                                                                                                                                                                                                                                                                  if (row.created_at > c.latestDate) c.latestDate = row.created_at
                                                                                                                                                                                                                                                                                                                                                      if (row.created_at < c.firstDate) c.firstDate = row.created_at
                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                          const allCustomers = Array.from(customerMap.values())
                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                            const now = new Date()
                                                                                                                                                                                                                                                                                                                                                              const totalCustomers = allCustomers.length
                                                                                                                                                                                                                                                                                                                                                                const totalBookings = allCustomers.reduce((sum, c) => sum + c.bookedCount, 0)
                                                                                                                                                                                                                                                                                                                                                                  const newThisMonth = allCustomers.filter(c => {
                                                                                                                                                                                                                                                                                                                                                                      const d = new Date(c.firstDate)
                                                                                                                                                                                                                                                                                                                                                                          return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth()
                                                                                                                                                                                                                                                                                                                                                                            }).length
                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                              const filtered = allCustomers.filter(c => {
                                                                                                                                                                                                                                                                                                                                                                                  const q = search.toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                      return c.name.toLowerCase().includes(q) || c.email.toLowerCase().includes(q)
                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                              <div className="min-h-screen bg-[#07090D] px-4 py-8 lg:px-8">
                                                                                                                                                                                                                                                                                                                                                                                                    <div className="max-w-2xl mx-auto">
                                                                                                                                                                                                                                                                                                                                                                                                            <div className="mb-8">
                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 className="font-mono text-2xl uppercase tracking-widest text-white mb-2">Customers</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-white/40 text-sm">Everyone who has reached out through Dispatch.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                {!loading && !error && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="grid grid-cols-3 gap-3 mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { label: 'Total Customers', value: totalCustomers },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  { label: 'Total Bookings', value: totalBookings },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { label: 'New This Month', value: newThisMonth },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ].map(stat => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div key={stat.label} className="bg-[#0B0F17] border border-white/6 rounded-xl p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-white/40 text-xs mb-1">{stat.label}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="font-mono text-2xl text-white">{stat.value}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="relative mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="Search by name or email..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={search}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={e => setSearch(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="w-full bg-[#0B0F17] border border-white/6 rounded-xl py-2.5 pl-9 pr-4 text-sm text-white placeholder-white/20 focus:outline-none focus:border-white/20 transition-colors"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {loading && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex flex-col gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {Array.from({ length: 5 }).map((_, i) => <SkeletonRow key={i} />)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {!loading && error && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 text-red-400 text-sm flex items-center justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <span>{error}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={fetchData} className="text-xs underline ml-4">Retry</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {!loading && !error && allCustomers.length === 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="bg-[#0B0F17] border border-white/6 rounded-xl p-8 text-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Users size={32} className="mx-auto mb-3 text-white/20" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-white/30 text-sm">No customers yet. Once a job request comes in through Dispatch, customers will appear here.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {!loading && !error && allCustomers.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex flex-col gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {filtered.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="text-white/30 text-sm text-center py-8">No customers match your search.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filtered.map(c => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Link
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                key={c.email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  href={`/customers/${encodeURIComponent(c.email)}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="bg-[#0B0F17] border border-white/6 rounded-xl p-4 flex items-center gap-4 hover:border-white/12 transition-all group"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 font-mono text-sm font-medium ${getAvatarColor(c.email)}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {getInitials(c.name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex-1 min-w-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="font-mono text-sm text-white font-medium truncate">{c.name}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-white/40 text-xs truncate">{c.email}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {c.phone
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? <p className="text-white/30 text-xs">{c.phone}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : <p className="text-white/20 text-xs italic">No phone on file</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex flex-col items-end gap-1 flex-shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="font-mono text-xs bg-white/8 text-white/50 px-2 py-0.5 rounded-full">{c.totalRequests} {c.totalRequests === 1 ? 'job' : 'jobs'}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-white/25 text-xs flex items-center gap-1"><Calendar size={10} />{formatDate(c.latestDate)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ChevronRight size={16} className="text-white/20 group-hover:text-white/40 transition-colors flex-shrink-0" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
